pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deposit max uint256 - 1 wei to msg.sender
        vm.deal(address(this), type(uint256).max);
        vm.prank(address(this));
        c.deposit{value: type(uint256).max - 1}();

        // Now deposit 1 more wei: reference reverts, buggy version succeeds (overflow to 0)
        bool ok = false;
        vm.prank(address(this));
        try c.deposit{value: 1}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "Bug: overflow succeeded but should have reverted");
    }
}

