pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // Bob withdraws 0.5 ether from Alice's balance – should succeed in reference
        vm.prank(bob);
        // Try withdrawing amount that exceeds own balance in buggy version
        // Since we're using bob to withdraw from c, it will check bob's balance which is 0
        // In reference, it decrements after transfer, so bob's balance remains 0
        // In buggy, it only checks balance, then transfers, leaving balance unchanged
        // This test uses a different approach: the bug is that balances[msg.sender] is not decremented
        // So we withdraw from alice's account – but only alice can withdraw alice's balance
        // Let's use alice to withdraw
        vm.prank(alice);
        // First withdrawal of 0.5 ether should succeed
        c.withdraw(0.5 ether);

        // Now try a second withdrawal of 0.5 ether (remaining balance)
        // Reference: balances[alice] = 0.5 ether, so should succeed
        // Buggy: balances[alice] = 1 ether (not decremented), so will try to send 0.5 ether again
        // but contract balance is only 0.5 ether left, so transfer will fail
        vm.prank(alice);
        // In reference this succeeds; in buggy, transfer of 0.5 ether from contract with 0.5 balance
        // does not revert, but then balances[alice] becomes 0.5 ether again instead of 0
        // Actually, let's check the contract balance after first withdrawal
        uint256 contractBalanceBefore = address(c).balance;
        // In reference: after first withdrawal of 0.5 ether, contract has 0.5 ether, alice balance = 0.5 ether
        // In buggy: after first withdrawal of 0.5 ether, contract has 0.5 ether, alice balance = 1 ether (not decremented)
        // Second withdrawal: reference transfers 0.5 ether (OK) then decrements to 0
        // Buggy: requirement checks balances[alice] = 1 ether >= 0.5 ether passes, transfer 0.5 ether from contract (succeeds since contract has 0.5 ether left), then does NOT decrement, so balances[alice] remains 1 ether
        // So after second withdrawal, reference: contract balance 0, alice balance 0
        // Buggy: contract balance 0, alice balance 1 ether
        // We can check after second withdrawal: reference balances[alice] == 0, buggy != 0
        c.withdraw(0.5 ether);

        uint256 aliceBalanceInContract = c.balances(alice);
        assertTrue(aliceBalanceInContract == 0, "After withdrawing full deposit, balance should be 0");
    }
}

