pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: Alice has 1 wei
        address alice = address(0x1234);
        vm.deal(alice, 1 wei);

        // Alice deposits 1 wei
        vm.prank(alice);
        c.deposit{value: 1 wei}();

        // Alice withdraws 1 wei; this should succeed in reference, fail in buggy
        vm.prank(alice);
        // Use try/catch to capture success/failure
        bool success;
        try c.withdraw(1 wei) {
            success = true;
        } catch {
            success = false;
        }

        // In reference, transfer of 1 wei succeeds, so withdraw succeeds.
        // In buggy, call{value:1} reentrancy guard/malicious receiver causes revert, withdraw fails.
        // Thus success is true in reference, false in buggy.
        assertTrue(success);
    }
}

