        address bob = address(0x5678);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.deposit{value: 1 wei}();

        // Bob (non-creator) tries to migrateTo himself — in reference, transfer reverts; in buggy, call succeeds
